import pdfplumber
import pandas as pd
import json

def normalize_salary(val):
    if pd.isna(val) or val == '': return 0
    if isinstance(val, str):
        return int(val.replace(',', ''))
    return int(val)

def normalize_int(val):
    if pd.isna(val) or val == '': return 0
    return int(val)

def normalize_float(val):
    if pd.isna(val) or val == '': return 0.0
    return float(val)

def extract_pdf_data(file_path):
    data = []
    headers = ['ID', 'First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']
    with pdfplumber.open(file_path) as pdf:
        for page in pdf.pages:
            tables = page.extract_tables()
            for table in tables:
                if not table: continue
                for row in table:
                    if not row or len(row) < 9: continue
                    # Skip header row if it's the literal header
                    if row[0] == 'ID': continue
                    # Sometimes headers are missed or weirdly formatted, 
                    # but if it doesn't start with EMP, it's probably not a row we want 
                    # unless it's the header.
                    if not str(row[0]).startswith('EMP'): continue

                    record = {headers[i]: row[i] for i in range(9)}
                    # Normalize types
                    record['Salary'] = normalize_salary(record['Salary'])
                    record['Years'] = normalize_int(record['Years'])
                    record['Score'] = normalize_float(record['Score'])
                    data.append(record)
    return pd.DataFrame(data)

def main():
    pdf_df = extract_pdf_data('employees_backup.pdf')
    xlsx_df = pd.read_excel('employees_current.xlsx')

    # Ensure Excel types are correct
    xlsx_df['Salary'] = xlsx_df['Salary'].astype(int)
    xlsx_df['Years'] = xlsx_df['Years'].astype(int)
    xlsx_df['Score'] = xlsx_df['Score'].astype(float)

    pdf_df = pdf_df.set_index('ID')
    xlsx_df = xlsx_df.set_index('ID')

    deleted_employees = sorted([id for id in pdf_df.index if id not in xlsx_df.index])

    modified_employees = []

    common_ids = sorted([id for id in pdf_df.index if id in xlsx_df.index])

    fields = ['First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']

    for eid in common_ids:
        old_row = pdf_df.loc[eid]
        new_row = xlsx_df.loc[eid]

        for field in fields:
            old_val = old_row[field]
            new_val = new_row[field]

            # For floats, use a small epsilon for comparison if needed, 
            # but here they seem to be simple decimals.
            if old_val != new_val:
                modified_employees.append({
                    "id": eid,
                    "field": field,
                    "old_value": old_val,
                    "new_value": new_val
                })

    # Sort modified_employees by ID
    modified_employees.sort(key=lambda x: x['id'])

    report = {
        "deleted_employees": deleted_employees,
        "modified_employees": modified_employees
    }

    with open('diff_report.json', 'w') as f:
        json.dump(report, f, indent=2)

if __name__ == '__main__':
    main()

